mapper.update:
UPDATE kb_chunk SET kb_doc_id = #{kbDocId}
WHERE tenant_id = #{tenantId}
  AND deleted = 0

  AND kb_doc_id <> #{kbDocId}

  AND chunk_key IN
#{k}

mapper.select:
SELECT chunk_key AS chunk_key, content_hash AS content_hash
FROM kb_chunk
WHERE tenant_id = #{tenantId}
  AND chunk_key LIKE #{prefix}
  AND deleted = 0

SELECT c.id AS id, c.chunk_key AS chunk_key, c.chunk_text AS chunk_text, c.chunk_type AS chunk_type, d.id AS source_doc_id, d.title AS source_doc_title, 1 - (c.embedding <=> CAST(#{queryVector} AS vector)) AS score FROM kb_chunk c JOIN kb_doc d ON d.id = c.kb_doc_id WHERE c.tenant_id = #{tenantId} AND c.deleted = 0 AND d.deleted = 0 AND d.is_active = 1
AND c.chunk_type = #{clauseType}
ORDER BY c.embedding <=> CAST(#{queryVector} AS vector) LIMIT #{limit}

SELECT c.id AS id, c.chunk_key AS chunk_key, c.chunk_text AS chunk_text, c.chunk_type AS chunk_type, d.id AS source_doc_id, d.title AS source_doc_title, ts_rank_cd(c.tsv, plainto_tsquery('crag_cn', #{query})) AS score FROM kb_chunk c JOIN kb_doc d ON d.id = c.kb_doc_id WHERE c.tenant_id = #{tenantId} AND c.deleted = 0 AND d.deleted = 0 AND d.is_active = 1 AND c.tsv @@ plainto_tsquery('crag_cn', #{query})
AND c.chunk_type = #{clauseType}
ORDER BY score DESC LIMIT #{limit}
